#!/usr/bin/env python3
"""Isolated SRE benchmark HTTP service.

Serves 127.0.0.1:<config port> and returns the configured status code
with body 'benchmark-ready'.
"""
import json
import pathlib
from http.server import BaseHTTPRequestHandler, HTTPServer

BASE_DIR = pathlib.Path(__file__).resolve().parent
CONFIG_PATH = BASE_DIR / "config.json"


def load_config():
    with CONFIG_PATH.open("r", encoding="utf-8") as fh:
        cfg = json.load(fh)
    if not isinstance(cfg, dict):
        raise ValueError("config.json must contain a JSON object")
    port = int(cfg.get("port", 18908))
    status = int(cfg.get("status", 200))
    return port, status


PORT, STATUS = load_config()
BODY = b"benchmark-ready"


class Handler(BaseHTTPRequestHandler):
    server_version = "SreBench/1.0"

    def _respond(self, include_body=True):
        self.send_response(STATUS)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(BODY) if include_body else 0))
        self.end_headers()
        if include_body:
            self.wfile.write(BODY)

    def do_GET(self):
        try:
            self._respond(True)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def do_HEAD(self):
        try:
            self._respond(False)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def log_message(self, fmt, *args):
        return


def main():
    server = HTTPServer(("127.0.0.1", PORT), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()

